-- Student identity chain: tb_students.student_id becomes the VARCHAR business id ({school short code}ST{nnn}, e.g. DPS001ST001),
-- generated by the app once when the student record is created and reused as tb_users.org_user_id when a login is created.
--
-- DESTRUCTIVE: drops and recreates the student / admission tables. Only run this on an environment whose students,
-- guardians-links, enrollments and admissions can be thrown away (the DB was confirmed clean of that data).
-- tb_guardians is NOT dropped: nothing about it changes, so recreating it "exactly as it was" would only lose rows.
--
-- Run order:
--   1. Docs/smss-users-login-id-and-school-short-code.sql   (username -> display_name, tb_schools.school_short_code)
--   2. this file
--   3. start the API build that contains the varchar StudentId mapping
-- Every school that should admit / onboard students needs a school_short_code (see the end of this file): schools registered
-- before the short code existed have NULL and are refused with "This school has no short code configured".

BEGIN;

-- The login no longer needs its own link to the student: tb_users.org_user_id IS the student id.
-- (Added by smss-users-login-id-and-school-short-code.sql; harmless if it was never added.) Must go BEFORE tb_students is dropped.
DROP INDEX IF EXISTS public.uq_tb_users_student;
ALTER TABLE public.tb_users DROP CONSTRAINT IF EXISTS fk_tb_users_student;
ALTER TABLE public.tb_users DROP COLUMN IF EXISTS student_id;

-- 1. drop in dependency order (children first)
DROP TABLE IF EXISTS public.tb_student_guardians;
DROP TABLE IF EXISTS public.tb_admission_documents;
DROP TABLE IF EXISTS public.tb_admissions;
DROP TABLE IF EXISTS public.tb_student_enrollments;
DROP TABLE IF EXISTS public.tb_students;

-- 2. tb_students: student_id is the app-generated varchar primary key; every column added incrementally before
--    (aadhar_number, profile_photo_url) is part of the CREATE
CREATE TABLE public.tb_students
(
    student_id           varchar(20)  NOT NULL,
    school_id            varchar(100) NOT NULL,
    admission_number     varchar(50)  NOT NULL,
    first_name           varchar(100) NOT NULL,
    middle_name          varchar(100),
    last_name            varchar(100) NOT NULL,
    date_of_birth        date         NOT NULL,
    gender_id            integer,
    blood_group_id       integer,
    student_category_id  integer,
    admission_type_id    bigint       NOT NULL,
    admission_date       date         NOT NULL,
    aadhar_number        varchar(20),
    email                varchar(150),
    mobile_number        varchar(20),
    address_line1        varchar(200),
    address_line2        varchar(200),
    country_id           integer,
    state_id             integer,
    district_id          integer,
    city_id              integer,
    pincode              varchar(10),
    profile_photo_url    text,
    status_id            integer      NOT NULL,
    created_at           timestamptz  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at           timestamptz  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT tb_students_pkey PRIMARY KEY (student_id),
    CONSTRAINT fk_tb_students_school FOREIGN KEY (school_id) REFERENCES public.tb_schools (school_id),
    CONSTRAINT fk_tb_students_status FOREIGN KEY (status_id) REFERENCES public.lut_status (sid),
    CONSTRAINT uq_tb_students_school_admno UNIQUE (school_id, admission_number)
);
CREATE INDEX idx_tb_students_school_id ON public.tb_students (school_id);
CREATE UNIQUE INDEX uq_tb_students_school_aadhar ON public.tb_students (school_id, aadhar_number) WHERE aadhar_number IS NOT NULL;

-- 3. tb_student_enrollments (student_id: bigint -> varchar(20))
CREATE TABLE public.tb_student_enrollments
(
    enrollment_id     bigint       GENERATED ALWAYS AS IDENTITY,
    school_id         varchar(100) NOT NULL,
    student_id        varchar(20)  NOT NULL,
    academic_year_id  bigint       NOT NULL,
    class_section_id  bigint       NOT NULL,
    roll_number       varchar(30),
    enrollment_date   date         NOT NULL,
    admission_type_id bigint       NOT NULL,
    status_id         integer      NOT NULL,
    created_at        timestamptz  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at        timestamptz  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT tb_student_enrollments_pkey PRIMARY KEY (enrollment_id),
    CONSTRAINT fk_tb_enrollments_school  FOREIGN KEY (school_id)  REFERENCES public.tb_schools (school_id),
    CONSTRAINT fk_tb_enrollments_status  FOREIGN KEY (status_id)  REFERENCES public.lut_status (sid),
    CONSTRAINT fk_tb_enrollments_student FOREIGN KEY (student_id) REFERENCES public.tb_students (student_id),
    CONSTRAINT uq_tb_enrollments_student_year UNIQUE (student_id, academic_year_id)
);
CREATE INDEX idx_tb_enrollments_school_id ON public.tb_student_enrollments (school_id);

-- 4. tb_student_guardians (student_id: bigint -> varchar(20)); tb_guardians is untouched
CREATE TABLE public.tb_student_guardians
(
    student_guardian_id  bigint      GENERATED ALWAYS AS IDENTITY,
    student_id           varchar(20) NOT NULL,
    guardian_id          bigint      NOT NULL,
    relationship         varchar(30) NOT NULL,
    is_primary           boolean     NOT NULL DEFAULT false,
    is_emergency_contact boolean     NOT NULL DEFAULT false,
    can_pickup_student   boolean     NOT NULL DEFAULT false,
    created_at           timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at           timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT tb_student_guardians_pkey PRIMARY KEY (student_guardian_id),
    CONSTRAINT fk_tb_student_guardians_student  FOREIGN KEY (student_id)  REFERENCES public.tb_students (student_id),
    CONSTRAINT fk_tb_student_guardians_guardian FOREIGN KEY (guardian_id) REFERENCES public.tb_guardians (guardian_id),
    CONSTRAINT uq_tb_student_guardians UNIQUE (student_id, guardian_id)
);

-- 5. tb_admissions (student_id: bigint -> varchar(20), nullable: only set once the application is ADMITTED)
--    The new FK to tb_students is the one deliberate addition (there was none on the bigint column).
CREATE TABLE public.tb_admissions
(
    admission_id           bigint       GENERATED ALWAYS AS IDENTITY,
    school_id              varchar(100) NOT NULL,
    application_number     varchar(50)  NOT NULL,
    academic_year_id       bigint       NOT NULL,
    applied_class_id       bigint       NOT NULL,
    admission_type_id      bigint       NOT NULL,
    applicant_first_name   varchar(100) NOT NULL,
    applicant_middle_name  varchar(100),
    applicant_last_name    varchar(100) NOT NULL,
    date_of_birth          date         NOT NULL,
    gender_id              integer,
    blood_group_id         integer,
    student_category_id    integer,
    aadhar_number          varchar(20),
    student_nation_id      varchar(50),
    email                  varchar(150),
    mobile_number          varchar(20),
    address_line1          varchar(200),
    address_line2          varchar(200),
    country_id             integer,
    state_id               integer,
    district_id            integer,
    city_id                integer,
    pincode                varchar(10),
    guardian_name          varchar(150) NOT NULL,
    guardian_relationship  varchar(30)  NOT NULL,
    guardian_mobile_number varchar(20)  NOT NULL,
    guardian_email         varchar(150),
    application_date       date         NOT NULL,
    status_id              integer      NOT NULL,
    reviewed_by            bigint,
    reviewed_at            timestamptz,
    decision_remarks       text,
    rejection_reason       text,
    approved_by            bigint,
    approved_at            timestamptz,
    student_id             varchar(20),
    enrollment_id          bigint,
    created_at             timestamptz  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at             timestamptz  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT tb_admissions_pkey PRIMARY KEY (admission_id),
    CONSTRAINT fk_tb_admissions_school  FOREIGN KEY (school_id)  REFERENCES public.tb_schools (school_id),
    CONSTRAINT fk_tb_admissions_status  FOREIGN KEY (status_id)  REFERENCES public.lut_status (sid),
    CONSTRAINT fk_tb_admissions_student FOREIGN KEY (student_id) REFERENCES public.tb_students (student_id),
    CONSTRAINT uq_tb_admissions_school_appno UNIQUE (school_id, application_number)
);
CREATE INDEX idx_tb_admissions_school_id ON public.tb_admissions (school_id);
CREATE INDEX idx_tb_admissions_status_id ON public.tb_admissions (status_id);
CREATE UNIQUE INDEX uq_tb_admissions_school_aadhar ON public.tb_admissions (school_id, aadhar_number) WHERE aadhar_number IS NOT NULL;

-- 6. tb_admission_documents (no student_id column: unchanged apart from being recreated)
CREATE TABLE public.tb_admission_documents
(
    admission_document_id bigint      GENERATED ALWAYS AS IDENTITY,
    admission_id          bigint      NOT NULL,
    document_type_id      bigint      NOT NULL,
    document_url          text        NOT NULL,
    is_verified           boolean     NOT NULL DEFAULT false,
    verified_by           bigint,
    verified_at           timestamptz,
    remarks               text,
    created_at            timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at            timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT tb_admission_documents_pkey PRIMARY KEY (admission_document_id),
    CONSTRAINT fk_tb_admission_documents_admission FOREIGN KEY (admission_id) REFERENCES public.tb_admissions (admission_id),
    CONSTRAINT fk_tb_admission_documents_doctype   FOREIGN KEY (document_type_id) REFERENCES public.tb_document_types (document_type_id)
);
CREATE INDEX idx_tb_admission_documents_admission_id ON public.tb_admission_documents (admission_id);

-- 7. One-time data fix: the Super Admin's display_name. Only runs when the username -> display_name rename (file 1) is applied.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_schema = 'public' AND table_name = 'tb_users' AND column_name = 'display_name') THEN
        UPDATE public.tb_users SET display_name = 'Akshay Upadhayay' WHERE org_user_id = 'SUAD001';
    ELSE
        RAISE NOTICE 'tb_users.display_name does not exist yet - run smss-users-login-id-and-school-short-code.sql first';
    END IF;
END $$;

COMMIT;

-- OPTIONAL, run by hand: give existing schools a short code so they can admit / onboard students. The code is the
-- first part of every student id (FTS001 -> FTS001ST001); it must be unique, up to 10 characters, and is never changed.
--   UPDATE public.tb_schools SET school_short_code = 'FTS001' WHERE school_id = 'sch2026006';
